/**
 * data.js — Static reference data for WeatherGPT.
 *
 * This file has no logic: it only holds content that used to live inline in
 * app.js (translations, the India city directory, demo weather seeds, mock
 * alerts, and climate-series parameters). Splitting it out keeps app.js
 * focused on behavior and makes this data easy to find/update independently
 * (e.g. handing translation updates to a translator, or wiring CITIES up to
 * a real backend later).
 *
 * Load order: data.js must load BEFORE weather-api.js and app.js.
 */

